package com.healthwise.user.controller;
import com.healthwise.security.CurrentUser; import com.healthwise.user.dto.UserDtos.*; import com.healthwise.user.service.UserService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
/** Authenticated user profile endpoints. */
@RestController @RequestMapping("/api/v1/users") public class UserController {private final UserService service;public UserController(UserService s){service=s;}@GetMapping("/me")public Response me(@AuthenticationPrincipal CurrentUser u){return service.me(u.id());}@PutMapping("/me")public Response update(@AuthenticationPrincipal CurrentUser u,@Valid @RequestBody Update d){return service.update(u.id(),d);}@DeleteMapping("/me")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@AuthenticationPrincipal CurrentUser u){service.delete(u.id());}@PutMapping("/password")@ResponseStatus(HttpStatus.NO_CONTENT)public void password(@AuthenticationPrincipal CurrentUser u,@Valid @RequestBody PasswordUpdate d){service.password(u.id(),d);}}
